#!/bin/sh

# cleanup
rm -f counter_ch.vcd
rm -rf obj_dir

# run Verilator to translate Verilog into C++, including C++ testbench
verilator -Wall --cc --trace counter_ch.sv --exe counter_tb_ch.cpp

# build C++ project via make automatically generated by Verilator
make -j -C obj_dir/ -f Vcounter_ch.mk Vcounter_ch

# run executable simulation file
obj_dir/Vcounter_ch